FuncDef.Code:
mat2 cameraOpDefault_Rot(float a)
{
    float s = sin(a), c = cos(a);
    return mat2(c, -s, s, c);
}

void cameraOpDefault(inout vec3 ro, inout vec3 rd, in vec2 fragCoord)
{
    // TODO: optimise...

    // input
    vec2 rotation       = vec2(cameraRotationPitch, cameraRotationYaw);
    float distance      = cameraDistanceToTarget;
    float zoom          = cameraZoom;

    // ray in view space
    vec3 ray = vec3(0.0);
    ray.xy = fragCoord.xy - iResolution.xy * 0.5;
    ray.z = iResolution.y*zoom;

    // roll rotation
    ray.xy = SDFG_MUL(cameraOpDefault_Rot(cameraRotationRoll), ray.xy);

    // pitch rotation
    ray.yz = SDFG_MUL(cameraOpDefault_Rot(cameraRotationPitch), ray.yz);

    // yaw rotation
    ray.xz = SDFG_MUL(cameraOpDefault_Rot(-cameraRotationYaw), ray.xz);

    ray = normalize(ray);

    // calculate offset (from camera pos to target)
    vec3 offset = vec3(0.0, 0.0, 1.0);

    // roll rotation
    offset.xy = SDFG_MUL(cameraOpDefault_Rot(cameraRotationRoll), offset.xy);

    // pitch rotation
    offset.yz = SDFG_MUL(cameraOpDefault_Rot(cameraRotationPitch), offset.yz);

    // yaw rotation
    offset.xz = SDFG_MUL(cameraOpDefault_Rot(-cameraRotationYaw), offset.xz);

    offset = normalize(offset);

    // camera position (ray origin)
    ro = cameraTargetPosition - distance * offset;

    // camera dir (ray dir)
    rd = ray;
}
